import itertools
import json
from collections import deque

names = [
    "Garza Tower", "Yates House", "Zimmer House", "Flores Tower",
    "Lynch Building", "King Building", "Meyer Building", "Ortiz Building"
]
classes = [1, 3, 3, 1, 2, 2, 2, 2]
weights = {1: 4, 2: 2, 3: 1}
initial = (0, 0, 0, 1, 1, 2, 2, 2)
by_class = {
    c: [i for i, building_class in enumerate(classes) if building_class == c]
    for c in (1, 2, 3)
}

# Every permissible trade, represented by the two exchanged packages.
trades = []
for indices in by_class.values():
    for a, b in itertools.combinations(indices, 2):
        trades.append(((a,), (b,)))
for a in by_class[1]:
    for pair in itertools.combinations(by_class[2], 2):
        trades.append(((a,), pair))
for a in by_class[2]:
    for pair in itertools.combinations(by_class[3], 2):
        trades.append(((a,), pair))

# Exhaust the finite ownership graph; each trade is between two companies.
distance = {initial: 0}
queue = deque([initial])
while queue:
    state = queue.popleft()
    for left, right in trades:
        owner_left = state[left[0]]
        owner_right = state[right[0]]
        if owner_left == owner_right:
            continue
        if any(state[i] != owner_left for i in left):
            continue
        if any(state[i] != owner_right for i in right):
            continue
        successor = list(state)
        for i in left:
            successor[i] = owner_right
        for i in right:
            successor[i] = owner_left
        successor = tuple(successor)
        if successor not in distance:
            distance[successor] = distance[state] + 1
            queue.append(successor)

options = {
    "A": (0, frozenset([4, 6, 7])),
    "B": (1, frozenset([0, 6])),
    "C": (1, frozenset([5, 6, 7])),
    "D": (2, frozenset([3, 1])),
    "E": (2, frozenset([0, 4])),
}
evidence = {}
impossible = []
for label, (company, target) in options.items():
    matches = [
        d for state, d in distance.items()
        if frozenset(i for i, owner in enumerate(state) if owner == company)
        == target
    ]
    evidence[label] = {
        "reachable": bool(matches),
        "minimum_trades": min(matches) if matches else None,
        "target_value_units": sum(weights[classes[i]] for i in target),
    }
    if not matches:
        impossible.append(label)

print(json.dumps({
    "final_answer": impossible[0] if len(impossible) == 1 else "UNSUPPORTED",
    "evidence": {
        "value_units_by_class": weights,
        "initial_company_value_units": [
            sum(weights[classes[i]] for i, owner in enumerate(initial)
                if owner == company)
            for company in range(3)
        ],
        "exhaustively_reached_states": len(distance),
        "options": evidence,
    }
}, separators=(",", ":")))
